import{_ as e,o as a,a as i,b as r}from"./app.C41L12d5.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"数学计算","link":"/api/SIMD-API/adv_api/math_compute/math_compute"},{"text":"BitwiseNot接口","link":"/api/SIMD-API/adv_api/math_compute/BitwiseNot_interface/BitwiseNot_interface"},{"text":"GetBitwiseNotTmpBufferFactorSize","link":"/api/SIMD-API/adv_api/math_compute/BitwiseNot_interface/GetBitwiseNotTmpBufferFactorSize"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/math_compute/BitwiseNot_interface/GetBitwiseNotTmpBufferFactorSize.md","filePath":"api/SIMD-API/adv_api/math_compute/BitwiseNot_interface/GetBitwiseNotTmpBufferFactorSize.md","outlineHeaders":[{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1785986301000}'),o={name:"api/SIMD-API/adv_api/math_compute/BitwiseNot_interface/GetBitwiseNotTmpBufferFactorSize.md"};function d(n,t,p,s,c,l){return a(),i("div",null,[...t[0]||(t[0]=[r(`<div><article class="markdown-body"><h1>GetBitwiseNotTmpBufferFactorSize</h1><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>该接口用于获取maxLivedNodeCount和extraBuf，在固定空间大小的情况下，通过maxLivedNodeCount和extraBuf可以推算算子单次最大计算元素数量。maxLivedNodeCount表示临时空间是单次计算数据量所占空间的多少倍；extraBuf表示使用的额外临时空间大小。</p><p>推算示例如下：</p><ul><li><p>算子实现需要调用BitwiseNot接口，开发者为其预留currBuff大小的空间，利用GetBitwiseNotTmpBufferFactorSize接口得到maxLivedNodeCount、extraBuf输出值，可推导算子单次最大计算元素数量为：</p><p><strong>currentShapeSize = (currBuff - extraBuf) / maxLivedNodeCount / typeSize</strong></p></li><li><p>算子实现需要调用两个kernel侧API KernelIntf1、KernelIntf2，利用两个GetXxxTmpBufferFactorSize（其中Xxx为需要调用的两个高阶API）接口的两组输出值(maxLivedNodeCount、extraBuf)以及当前现有的临时空间，推导单次最大计算元素数量currentShapeSize为：</p><p><strong>currentShapeSize1 = (currBuff - extraBuf1) / maxLivedNodeCount1 / typeSize</strong></p><p><strong>currentShapeSize2 = (currBuff - extraBuf2) / maxLivedNodeCount2 / typeSize</strong></p><p><strong>currentShapeSize = min(currentShapeSize1, currentShapeSize2)</strong></p></li></ul><p>注意上文中的currBuff表示接口计算可用的空间，需要去除用户输入输出等空间；另外，接口获取的maxLivedNodeCount值可能为0，计算时需要判断该值非0，避免除零错误。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>void GetBitwiseNotTmpBufferFactorSize(const platform_ascendc::PlatformAscendC&amp; ascendcPlatform,const uint32_t typeSize, uint32_t&amp; maxLivedNodeCount, uint32_t&amp; extraBuf)
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数列表</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>功能</th></tr></thead><tbody><tr><td>ascendcPlatform</td><td>输入</td><td>输入的平台信息。PlatformAscendC的定义请参见<a href="../../../../Utils-API/platform_info/PlatformAscendC/constructor_and_destructor.html">构造及析构函数</a>。</td></tr><tr><td>typeSize</td><td>输入</td><td>输入的数据类型大小，单位为字节。</td></tr><tr><td>maxLivedNodeCount</td><td>输出</td><td>最大存活节点数，表示临时空间是单次计算数据量所占空间的多少倍。</td></tr><tr><td>extraBuf</td><td>输出</td><td>使用的额外临时空间大小，单位为字节。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><p>当利用maxLivedNodeCount、extraBuf反推出的currentShapeSize * typeSize &lt; 256B时，currentShapeSize按照256B/typeSize的值向上取整。</p><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>完整的调用样例请参考<a href="../more_examples.html">更多样例</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>uint32_t maxLivedNodeCount = 0;
uint32_t extraBuf = 0;
auto plat = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());
AscendC::GetBitwiseNotTmpBufferFactorSize(plat, typeSize, maxLivedNodeCount, extraBuf);
</code></pre></div></article></div>`,1)])])}const f=e(o,[["render",d]]);export{u as __pageData,f as default};
